void load_vocab(const char*f){
  FILE*p=fopen(f,"r");
  char s[256];fgets(s,256,p);
  for(tn=0;tn<V&&fgets(s,256,p);tn++){
    s[strcspn(s,"\n")]=0;
    tok[tn]=malloc(strlen(s)+1);
    strcpy(tok[tn],s);
  }
  fclose(p);
}
void load_weights(const char*f){
  FILE*p=fopen(f,"rb");
  fread(w,4,E,p);
  fread(b,4,E,p);
  fclose(p);
}
int sample(float*l){
  int mx=0;
  for(int i=1;i<V;i++)if(l[i%E]>l[mx%E])mx=i;
  return mx;
}
int main(int c,char**v){
  if(c<4)return 1;
  load_vocab(v[2]);
  load_weights(v[1]);
  printf("%s",v[3]);
  float logits[E];
  for(int t=0;t<20;t++){
    memcpy(logits,w,sizeof(w));
    int s=sample(logits);
    if(s<tn)printf("%s",tok[s]);
    for(int i=0;i<E;i++)w[i]+=b[i]*0.001;
  }
  return 0;
}
